    public string SaveShipment(int id, string value)
    {
        var normalized = NormalizeShipment(value);
        return PersistShipment(id, normalized);
    }

    public string NormalizeShipment(string value)
    {
        return value.Trim();
    }

    public string PersistShipment(int id, string normalized)
    {
        return ShipmentRepository4.StoreShipment(id, normalized);
    }
}

public class ShipmentRepository4
{
    public static string StoreShipment(int id, string normalized)
    {
        return normalized + id.ToString();
    }
}

